use std::error::Error;
use std::fs::File;
use csv::Reader;

pub fn sum_column(path: &str, column: &str) -> Result<f64, Box<dyn Error>> {
    let mut rdr = Reader::from_reader(File::open(path)?);
    let headers = rdr.headers()?.clone();
    let col_idx = headers.iter().position(|h| h == column)
        .ok_or_else(|| format!("Column '{}' not found", column))?;
    let mut total = 0f64;
    for result in rdr.records() {
        let record = result?;
        total += record[col_idx].parse::<f64>()?;
    }
    Ok(total)
}
